"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[737],{28550:o=>{o.exports=JSON.parse('{"tag":{"label":"Workbook","permalink":"/docs/tags/workbook","allTagsPath":"/docs/tags","count":18,"items":[{"id":"BI Analytics/Dashboards/Generate dashboards/About generating dashboards with AI","title":"About AI generated dashboards","description":"The Generate Dashboard feature enables users to quickly create insightful dashboards tailored to their specific roles or needs. You can either select from predefined personas or define your own custom dashboard through natural language descriptions.","permalink":"/docs/BI Analytics/Dashboards/Generate dashboards/about-ai-generate-dashboards"},{"id":"Workbooks/About workbook","title":"About workbook","description":"Workbooks provide a versatile solution, empowering you to organize, analyze, and visualize your data with ease. Whether you are building dynamic reports or managing critical datasets, understanding the capabilities of workbooks is key to unlocking your data\'s full potential.","permalink":"/docs/Workbooks/about-workbook"},{"id":"Workbooks/Append or replace data in workbooks","title":"Append or replace data in workbooks","description":"You can append new data to existing workbooks or replace entire sheets with revised data. If you need to do any of the following, then appending the workbook with the required data or replacing the entire workbook is a good solution:","permalink":"/docs/Workbooks/append-replace-data-existing-workbooks"},{"id":"Workbooks/Column Extraction","title":"Column Extraction","description":"The Column Extraction feature enables you to automatically extract structured data fields from unstructured sources \u2014 such as meeting transcripts, recorded calls, or text documents \u2014 using an AI agent. Rather than manually reviewing lengthy content, you can configure an extraction pipeline that pulls specific fields into a structured workbook with minimal effort.","permalink":"/docs/Workbooks/column-extraction"},{"id":"Workbooks/Creating a blank workbook","title":"Creating a blank workbook","description":"To create a blank workbook, do the following:","permalink":"/docs/Workbooks/creating-blank-workbook"},{"id":"Workbooks/Creating a Workbook","title":"Creating a Workbook","description":"You can create a workbook in any of the following methods:","permalink":"/docs/Workbooks/creating-workbook"},{"id":"Workbooks/Creating links and joins in dynamic tables","title":"Creating links and joins in dynamic tables","description":"If you want to connect to specific records from another workbook in DataGOL, you create a Link. A Link is a direct relationship created between two different tables or workbooks. This is done by adding a specific column to a workbook and then manually or automatically connecting it to records in another workbook. Links are about connecting records and viewing related data within an existing workbook. They add a column to your current table.","permalink":"/docs/Workbooks/create-link-joins-dynamic tables"},{"id":"Workspaces/Deleting a workspace","title":"Deleting a workspace","description":"1.  On the Home page, from the left navigation panel, click Workspace. The Workspace page, which lists all the workspaces is displayed.","permalink":"/docs/Workspaces/deleting-workspace"},{"id":"Workspaces/Editing a workspace","title":"Editing a workspace","description":"1.  On the Home page, from the left navigation panel, click Workspace. The Workspace page, which lists all the workspaces is displayed.","permalink":"/docs/Workspaces/editing-workspace"},{"id":"BI Analytics/Dashboards/Generate dashboards/Generating dashboards with AI","title":"Generating dashboards with AI","description":"Generating dashboards with AI","permalink":"/docs/BI Analytics/Dashboards/Generate dashboards/about-workbook"},{"id":"Workspaces/Inviting users to join workspace or sharing workspace","title":"Inviting users to join workspace or sharing workspace","description":"To join a workspace, users are required to create an account. Without an account, access to the workspace is not possible.","permalink":"/docs/Workspaces/inviting-users-to-join-a-workspace-sharing-a-workspace"},{"id":"Workspaces/Joining open workspaces","title":"Joining open workspaces","description":"To join open workspaces, do the following:","permalink":"/docs/Workspaces/joining-open-workspaces"},{"id":"Workspaces/Leaving a workspace","title":"Leaving a workspace","description":"To leave a workspace, do the following:","permalink":"/docs/Workspaces/leaving-a-workspace"},{"id":"Workbooks/Publishing workbook from playground","title":"Publishing workbook from playground","description":"Refer to Publishing workbook from playground.","permalink":"/docs/Workbooks/publishing-workbook-from-playground"},{"id":"Workspaces/Requesting access to workspaces","title":"Requesting access to workspaces","description":"To request access to a workspace, do the following:","permalink":"/docs/Workspaces/requesting-access-to-workspace"},{"id":"Workbooks/Viewing workbook lineage","title":"Viewing workbook lineage","description":"The workbook Lineage view offers a visual representation of how data flows from raw sources through pipelines into workbooks, helping users trace, audit, and understand column-level transformations.","permalink":"/docs/Workbooks/viewing-workbook-lineage"},{"id":"Workbooks/Workbook API reference","title":"Workbook API reference","description":"Overview","permalink":"/docs/Workbooks/workbook-api-reference"},{"id":"Workbooks/Workbook as a MCP","title":"Workbook MCP (Model Context Protocol)","description":"Overview","permalink":"/docs/Workbooks/workbook-as-a-MCP"}],"unlisted":false}}')}}]);